cd /workspace/services/ingestion && cat > /tmp/test_kh.mjs << 'EOF'
import fetch from 'node-fetch';
const ELASTIC_SEARCH_URL = 'https://elastic.kulturhusetstadsteatern.se/khst-events';
const query = {
  size: 5,
  query: {
    bool: {
      must: [
        {
          range: {
            tixStartDate: {
              gte: 'now'
            }
          }
        }
      ]
    }
  },
  sort: [
    { tixStartDate: { order: 'asc' } }
  ]
};
try {
  const response = await fetch(ELASTIC_SEARCH_URL + '/_search', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'User-Agent': 'EventPulse/1.0',
    },
    body: JSON.stringify(query)
  });

  console.log('Status:', response.status);
  const data = await response.json();
  console.log('Hits total:', data.hits?.total?.value || data.hits?.total);
  console.log('Sample events:');
  if (data.hits?.hits) {
    data.hits.hits.forEach((h, i) => {
      console.log(`  ${i+1}. ${h._source?.drupalTitle || h._source?.tixName || 'Untitled'}`);
    });
  }
} catch (error) {
  console.error('Error:', error.message);
}
EOF



node /tmp/test_kh.mjs

